'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < data.length && data.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < data.length) {
    const c = data.charCodeAt(pos);
    if (c <= 32) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const parent = new Int32Array(N + 1);
const head = new Int32Array(N + 1);
head.fill(-1);
const nextSibling = new Int32Array(N + 1);

for (let v = 2; v <= N; v++) {
  const p = nextInt();
  parent[v] = p;
  nextSibling[v] = head[p];
  head[p] = v;
}

// Euler tour intervals for original subtrees.
const tin = new Int32Array(N + 1);
const tout = new Int32Array(N + 1);
const order = new Int32Array(N);
const stack = new Int32Array(N);
let stackSize = 0;
let orderSize = 0;

stack[stackSize++] = 1;
while (stackSize > 0) {
  const v = stack[--stackSize];
  tin[v] = orderSize;
  order[orderSize++] = v;
  for (let u = head[v]; u !== -1; u = nextSibling[u]) {
    stack[stackSize++] = u;
  }
}

const subtreeSize = new Int32Array(N + 1);
subtreeSize.fill(1);
for (let i = N - 1; i > 0; i--) {
  const v = order[i];
  subtreeSize[parent[v]] += subtreeSize[v];
}
for (let v = 1; v <= N; v++) {
  tout[v] = tin[v] + subtreeSize[v] - 1;
}

const Q = nextInt();
const type = new Int8Array(Q);
const arg1 = new Int32Array(Q);
const arg2 = new Int32Array(Q);

for (let i = 0; i < Q; i++) {
  type[i] = nextInt();
  arg1[i] = nextInt();
  if (type[i] === 1) arg2[i] = nextInt();
}

const blockSize = 80;
const sqrtN = Math.ceil(Math.sqrt(N));

const latestTime = new Int32Array(N + 1);
const bestNode = new Int32Array(N + 1);
const baseParent = new Int32Array(N + 1);
const baseDepth = new Int32Array(N + 1);
const blockTop = new Int32Array(N + 1);
const blockJump = new Int32Array(N + 1);

let segSize = 1;
while (segSize < N) segSize <<= 1;
const segTime = new Int32Array(segSize << 1);
const segNode = new Int32Array(segSize << 1);
const segVersion = new Int32Array(segSize << 1);
let version = 0;

function rangeUpdate(left, right, time, node) {
  let l = left + segSize;
  let r = right + segSize;
  while (l < r) {
    if (l & 1) {
      segVersion[l] = version;
      segTime[l] = time;
      segNode[l] = node;
      l++;
    }
    if (r & 1) {
      --r;
      segVersion[r] = version;
      segTime[r] = time;
      segNode[r] = node;
    }
    l >>= 1;
    r >>= 1;
  }
}

function pointQuery(index) {
  let i = index + segSize;
  let bestTime = 0;
  let best = 0;
  while (i > 0) {
    if (segVersion[i] === version && segTime[i] > bestTime) {
      bestTime = segTime[i];
      best = segNode[i];
    }
    i >>= 1;
  }
  return best;
}

function rebuildBase() {
  bestNode[0] = 0;
  baseParent[0] = 0;
  baseDepth[0] = 0;
  blockTop[0] = 0;
  blockJump[0] = 0;

  for (let v = 1; v <= N; v++) {
    const p = parent[v];
    let best = bestNode[p];
    if (latestTime[v] > latestTime[best]) best = v;
    bestNode[v] = best;

    baseParent[v] = bestNode[p] !== 0 ? bestNode[p] : p;
    baseDepth[v] = baseDepth[baseParent[v]] + 1;

    const rem = baseDepth[v] % sqrtN;
    if (rem === 0) {
      blockTop[v] = v;
      blockJump[v] = blockTop[baseParent[v]];
    } else {
      blockTop[v] = blockTop[baseParent[v]];
      blockJump[v] = 0;
    }
  }
}

function jumpBase(v, k) {
  while (k > 0 && v !== 0) {
    const rem = baseDepth[v] % sqrtN;
    if (rem > 0) {
      const steps = Math.min(k, rem);
      for (let i = 0; i < steps; i++) v = baseParent[v];
      k -= steps;
    } else if (k >= sqrtN) {
      v = blockJump[v];
      k -= sqrtN;
    } else {
      for (let i = 0; i < k; i++) v = baseParent[v];
      k = 0;
    }
  }
  return v;
}

const output = [];

for (let start = 0; start < Q; start += blockSize) {
  const end = Math.min(Q, start + blockSize);

  rebuildBase();
  version++;

  for (let i = start; i < end; i++) {
    if (type[i] === 2) {
      const v = arg1[i];
      const time = i + 1;
      latestTime[v] = time;
      rangeUpdate(tin[v], tout[v] + 1, time, v);
    } else {
      let cur = arg1[i];
      let remaining = arg2[i];

      while (remaining > 0) {
        const p = parent[cur];
        if (p === 0) {
          cur = jumpBase(cur, remaining);
          break;
        }

        const updatedAncestor = pointQuery(tin[p]);
        if (updatedAncestor === 0) {
          cur = jumpBase(cur, remaining);
          break;
        }

        cur = updatedAncestor;
        remaining--;
      }

      output.push(String(cur));
    }
  }
}

process.stdout.write(output.join('\n'));
